        'uniform_4': 0,  # 4 of same value
        'uniform_2_pair': 0,  # 2 of each of 2 different values
        'varied': 0,  # 3 different values
        'minority_1': 0,  # 3 of one, 1 of another
        'single_8': 0,  # all 8s
        'empty': 0,
    }

    out3_count = 0
    out4_count = 0

    for i, row in enumerate(out):
        for j, val in enumerate(row):
            block = []
            for di in range(2):
                for dj in range(2):
                    r, c = i*2 + di, j*2 + dj
                    if r < len(inp) and c < len(inp[0]):
                        block.append(inp[r][c])

            if not block:
                block_pattern_counts['empty'] += 1
                continue

            counts = Counter(block)
            vals = list(counts.keys())
            if len(vals) == 1:
                block_pattern_counts['uniform_4'] += 1
                if val == 3:
                    block_pattern_counts['single_8'] += 1  # Actually might not be 8
