def my_transform_v7(test_grid):
    inp = test_grid.astype(int)
    rows, cols = inp.shape
    out = np.zeros((rows, cols), dtype=int)
    out[:] = inp

    have_8_rows = sorted([r for r in range(rows) if 8 in inp[r]])
    if len(have_8_rows) < 1:
        return out

    marker_pos = np.argwhere(inp == 2)
    marker_row = marker_pos[0][0] if len(marker_pos) > 0 else None

    gap_ranges = {}
    for r in have_8_rows:
        gaps = [c for c in range(cols) if inp[r][c] != 8]
        gap_ranges[r] = gaps

    min_8 = have_8_rows[0]
    max_8 = have_8_rows[-1]

    for r in range(rows):
        if r in have_8_rows:
            for c in gap_ranges[r]:
                out[r, c] = 2
        elif r < min_8:
            if r != marker_row and gap_ranges[min_8]:
                first, last = gap_ranges[min_8][0], gap_ranges[min_8][-1]
                out[r, first:last+1] = 2
        elif r > max_8:
            if gap_ranges[max_8]:
                for c in gap_ranges[max_8]:
                    out[r, c] = 2
        else:
            # min_8 < r < max_8
            if r == max_8 - 1:
                out[r, :] = 2
            else:
                next_8 = min(x for x in have_8_rows if x > r)
                prev_8 = max(x for x in have_8_rows if x < r)

                if r == next_8 - 1:
                    if gap_ranges[next_8]:
                        first, last = gap_ranges[next_8][0], gap_ranges[next_8][-1]
                        out[r, first:last+1] = 2
                    else:
                        out[r, :] = 2
                else:
                    if r - prev_8 <= next_8 - r:
                        for c in gap_ranges.get(prev_8, []):
                            out[r, c] = 2
                    else:
                        for c in gap_ranges.get(next_8, []):
                            out[r, c] = 2

    return out

